def transform(g):
    R,C=len(g),len(g[0]); out=[]
    for i in range((R+1)//4):
        row=[]
        for j in range((C+1)//5):
            v=g[min(i*4+1,R-1)][min(j*5+1,C-1)]
            for rr,cc in [(i*4,j*5),(i*4,min(j*5+4,C-1)),(min(i*4+4,R-1),j*5),(min(i*4+4,R-1),min(j*5+4,C-1))]:
                if g[rr][cc] not in (3,4): v=g[rr][cc]
            row.append(v)
        out.append(row)
    return out
